import json,time,urllib.request,urllib.error,email.utils
from datetime import datetime,timezone
from decimal import Decimal,ROUND_HALF_UP
BASE='http://localhost:8080'
token=None
stats={}
def request(path,auth=True,method='GET'):
 global token
 while True:
  if auth and token is None:
   token=[REDACTED_SECRET]'/token',False,'POST')['token']
  req=urllib.request.Request(BASE+path,method=method,headers={'Authorization':'Bearer '+token} if auth else {})
  try:
   with urllib.request.urlopen(req,timeout=30) as res:
    return json.load(res)
  except urllib.error.HTTPError as e:
   body=e.read().decode()
   stats[str(e.code)]=stats.get(str(e.code),0)+1
   print('Retry',path,e.code,body,flush=True)
   if e.code==401 and auth:
    token=None
    continue
   retry=e.headers.get('Retry-After')
   if retry:
    try: delay=float(retry)
    except ValueError: delay=max(0,email.utils.parsedate_to_datetime(retry).timestamp()-time.time())
   else: delay=1
   time.sleep(delay)
  except (urllib.error.URLError,TimeoutError,ConnectionError,json.JSONDecodeError) as e:
   print('Retry',path,str(e),flush=True)
   time.sleep(1)
seen={}; duplicates=0; pages=[]; path='/orders?page=1'
while path:
 data=request(path)
 assert data['page']==len(pages)+1
 pages.append(data)
 for order in data['items']:
  oid=order['id']
  if oid in seen:
   assert seen[oid]==order, 'Conflicting duplicate '+oid
   duplicates+=1
  else: seen[oid]=order
 path=data['next']
 print('Fetched page',data['page'],'of',data['total_pages'],flush=True)
assert len(pages)==pages[-1]['total_pages']
start=datetime(2025,3,1,tzinfo=timezone.utc); end=datetime(2025,6,1,tzinfo=timezone.utc)
qual=[]; changed=[]
for order in seen.values():
 dt=datetime.fromisoformat(order['placed_at'].replace('Z','+00:00'))
 assert dt.tzinfo is not None
 inside=start<=dt.astimezone(timezone.utc)<end
 if order['status']=='shipped':
  if inside "'!= ('"'2025-03-01'<=order['placed_at'][:10]<='2025-05-31'): changed.append(order['id'])
  if inside: qual.append(order)
customers={}
for cid in sorted({o['customer_id'] for o in qual}):
 customer=request('/customers/'+cid)
 assert customer['id']==cid
 customers[cid]=customer
 if len(customers)%20==0: print('Cached customers',len(customers),flush=True)
regions=dict.fromkeys(['north','south','east','west'],0)
for o in qual:
 c=customers[o['customer_id']]; pct=c['discount_pct']
 assert type(pct) is int and 0<=pct<=100
 value=int((Decimal(o['amount_cents'])*Decimal(100-pct)/100).quantize(Decimal(1),rounding=ROUND_HALF_UP))
 assert value==(o['amount_cents']*(100-pct)+50)//100
 regions[c['region']]+=value
result={'total_cents':sum(regions.values()),'order_count':len(qual),'duplicates_skipped':duplicates,'by_region':regions}
assert len({o['id'] for o in qual})==len(qual)
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
with open('/tmp/reconciliation_audit.json','w') as f: json.dump({'pages':pages,'customers':customers,'stats':stats},f)
print(json.dumps(result),flush=True)
print('Unique orders',len(seen),'UTC boundary changes for shipped',changed,'retries',stats,flush=True)
